/* @lc app=leetcode id=2976 lang=kotlin */ class Solution { fun minimumCost(source: String, target: String, original: CharArray, changed: CharArray, cost: IntArray): Long = Array(26) { i -> LongArray(26) { j -> if (i == j) 0L else 1e12.toLong() } }.also { d -> original.indices.forEach { i -> (original[i] - 'a').let { u -> (changed[i] - 'a').let { v -> d[u][v] = minOf(d[u][v], cost[i].toLong()) } } } }.also { d -> (0 until 26).forEach { k -> (0 until 26).forEach { i -> (0 until 26).forEach { j -> d[i][j] = minOf(d[i][j], d[i][k] + d[k][j]) } } } }.let { d -> source.indices.fold(0L) { acc, i -> if (acc == -1L) -1L else d[source[i] - 'a'][target[i] - 'a'].let { c -> if (c >= 1e11.toLong()) -1L else acc + c } } } }